do $compras$
declare
  v_org bigint; v_gtq bigint; v_l record; v_n int := 0; v_a int := 0; v_ren int := 0; v_k int; v_prov int := 0; v_reg int := 0; v_doc int := 0; v_trx int; v_omit int; v_idp int := 0;
begin
  select id into v_org from public.organizaciones where codigo = '2';
  if v_org is null then raise notice 'No existe la organización 2.'; return; end if;
  select id into v_gtq from public.monedas where iso = 'GTQ';
  -- Carga de datos históricos: los períodos fiscales cerrados no la bloquean.
  perform set_config('fin.migracion', 'si', true);

